const revision = $json;

if (!revision.author_name || !revision.credentials || !revision.author_bio) {
  throw new Error('The Doctor Profiles row must be completed and marked Active before this article can move forward.');
}

if (!revision.article_id || !revision.current_package_json || !revision.revision_instruction) {
  throw new Error('No unprocessed marketing revision request is available.');
}

let currentPackage;
try {
  currentPackage = typeof revision.current_package_json === 'string'
    ? JSON.parse(revision.current_package_json)
    : revision.current_package_json;
} catch (error) {
  throw new Error('The current article package is not valid JSON: ' + error.message);
}

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['article_html', 'review_document_markdown', 'metadata'],
  properties: {
    article_html: { type: 'string' },
    review_document_markdown: { type: 'string' },
    metadata: {
      type: 'object',
      additionalProperties: false,
      required: ['h1', 'seo_title', 'slug', 'meta_description', 'primary_search_intent', 'word_count'],
      properties: {
        h1: { type: 'string' },
        seo_title: { type: 'string' },
        slug: { type: 'string' },
        meta_description: { type: 'string' },
        primary_search_intent: { type: 'string' },
        word_count: { type: 'integer' }
      }
    }
  }
};

const isPrestonwoodPilot = revision.campaign_id === 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
if (isPrestonwoodPilot && (revision.practice_id !== 'practice_test_001' || String(revision.doctor_id || '').toLowerCase() !== 'doctor_jdold_apexdp_com')) {
  throw new Error('The Prestonwood pilot requires the named test doctor and TEST001 practice.');
}
const practiceContext = {
  doctor_name: revision.doctor_name,
  doctor_author_name: revision.author_name,
  doctor_bio: revision.author_bio,
  doctor_profile_url: revision.profile_url,
  doctor_credentials: revision.credentials,
  practice_name: isPrestonwoodPilot ? 'Prestonwood Family Dentistry' : revision.practice_name,
  website_domain: isPrestonwoodPilot ? 'https://prestonwooddentistry.com' : revision.website_domain,
  publisher_config_reference: revision.publisher_config_reference,
  campaign_name: revision.campaign_name,
  campaign_month: revision.campaign_month,
  topic_title: revision.topic_title,
  topic_description: revision.topic_description,
  interview_guidance: revision.interview_guidance
};

const input = [
  'MARKETING REVISION REQUEST',
  revision.revision_instruction,
  '',
  'CURRENT ARTICLE VERSION',
  String(revision.current_version),
  '',
  'CURRENT PUBLICATION PACKAGE',
  JSON.stringify(currentPackage, null, 2),
  '',
  'ORIGINAL INTERVIEW TRANSCRIPT',
  revision.transcript || '',
  '',
  'PRIOR REVISION HISTORY',
  revision.revision_history_json || '[]',
  '',
  'PRACTICE CONTEXT',
  JSON.stringify(practiceContext, null, 2)
].join('\n');

return [{
  json: {
    ...revision,
    next_version: Number(revision.current_version) + 1,
    openai_body: {
      model: 'gpt-6-astra',
      tools: [{ type: 'web_search' }],
      include: ['web_search_call.action.sources'],
      instructions: "# Marketing Revision Master Prompt\n\nYou are revising an expert-authored dental article after a marketing reviewer\nrequested changes. Return the same complete publication package schema as the\ncurrent article: `article_html`, `review_document_markdown`, and `metadata`.\n\nUse the reviewer's written request first, then the original interview, the\ncurrent version, prior revision history, and authoritative research where\nfactual verification is needed. Revise the current article; do not start an\nunrelated draft. Preserve the interviewed clinician's authentic first-person\nvoice. Do not invent clinical experience, patient stories, personal opinions,\npractice procedures, or credentials. If a requested change conflicts with the\ninterview or reliable evidence, make only a defensible correction and explain\nthe limitation in the review document.\n\nPreserve the automation-managed visible byline and author-bio regions. Do not\ninvent, paraphrase, or independently add author credentials or biography text.\n\nKeep all unaffected, accurate material. Preserve confirmed WordPress Shortcoder\ntags exactly, especially `[sc name=\"practice_name\"][/sc]`; do not introduce\nlegacy `{{...}}` publishing tokens, invent shortcode names, or use generic\n`doctor_01`/`doctor_02` tags for the interviewed doctor. Production HTML must\nremain clean, with the five metadata comments before the H1 and no internal\nreview comments, script, style, or document wrapper tags.\n\nThe result must contain the full revised article HTML and full human-readable\nreview document, not a diff. The review document's article wording must match\nthe HTML. Update source notes, editorial notes, and review checklist wherever\nthe revision changes them. This revision returns to marketing review directly;\ndo not claim it received a new doctor approval.\n",
      input,
      text: {
        format: {
          type: 'json_schema',
          name: 'revised_article_publication_package',
          strict: true,
          schema
        }
      },
      max_output_tokens: 30000
    }
  }
}];

const response = $json;
const context = $('Prepare Marketing Revision Request').first().json;

const escapeAuthorHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');
const ensureArticleAuthorship = (sourceHtml) => {
  const authorName = String(context.author_name || context.doctor_name || '').trim();
  const credentials = String(context.credentials || '').trim();
  const authorBio = String(context.author_bio || '').trim();
  const profileUrl = String(context.profile_url || '').trim();
  if (!authorName || !credentials || !authorBio) {
    throw new Error('Verified author name, credentials, and bio are required before an article can be generated or revised.');
  }
  let result = String(sourceHtml || '')
    .replace(/\s*<!-- AAC_AUTHOR_BYLINE_START -->[\s\S]*?<!-- AAC_AUTHOR_BYLINE_END -->\s*/gi, '\n')
    .replace(/\s*<!-- AAC_AUTHOR_BIO_START -->[\s\S]*?<!-- AAC_AUTHOR_BIO_END -->\s*/gi, '\n');
  const h1 = result.match(/<h1(?:\s[^>]*)?>[\s\S]*?<\/h1>/i);
  if (!h1 || h1.index === undefined) throw new Error('Production HTML is missing its H1.');
  const displayName = [authorName, credentials].filter(Boolean).join(', ');
  const byline = '<!-- AAC_AUTHOR_BYLINE_START -->\n<p><strong>By ' + escapeAuthorHtml(displayName) + '</strong></p>\n<!-- AAC_AUTHOR_BYLINE_END -->';
  const profileLink = /^https:\/\//i.test(profileUrl)
    ? '\n<p><a href="' + escapeAuthorHtml(profileUrl) + '">Learn more about ' + escapeAuthorHtml(authorName) + '</a></p>'
    : '';
  const bio = '<!-- AAC_AUTHOR_BIO_START -->\n<h2>About ' + escapeAuthorHtml(authorName) + '</h2>\n<p>' + escapeAuthorHtml(authorBio) + '</p>' + profileLink + '\n<!-- AAC_AUTHOR_BIO_END -->';
  const insertAt = h1.index + h1[0].length;
  result = result.slice(0, insertAt) + '\n' + byline + result.slice(insertAt);
  return result.trim() + '\n\n' + bio;
};


if (response.error) {
  throw new Error('OpenAI article revision failed: ' + JSON.stringify(response.error));
}
if (response.status && response.status !== 'completed') {
  throw new Error('OpenAI revision response did not complete. Status: ' + response.status);
}

const message = (response.output || []).find((item) => item.type === 'message');
const outputText = message?.content?.find((item) => item.type === 'output_text')?.text;
if (!outputText) {
  throw new Error('OpenAI revision response did not contain structured output text.');
}

let publicationPackage;
try {
  publicationPackage = JSON.parse(outputText);
} catch (error) {
  throw new Error('Revised article package was not valid JSON: ' + error.message);
}

const html = ensureArticleAuthorship(publicationPackage.article_html || '');
const review = publicationPackage.review_document_markdown || '';
if (!html.trim() || !html.startsWith('<!-- SEO_TITLE:') || !html.includes('<h1>')) {
  throw new Error('Revised production HTML is empty or missing required metadata and H1.');
}
if (/<(?:html|head|body|script|style)(?:\s|>)/i.test(html)) {
  throw new Error('Revised production HTML contains a forbidden wrapper or executable/style tag.');
}
if (/<!--\s*(?:FACT CHECK|INTERVIEW BASIS|REVIEW NOTE|SOURCE|CLINICAL REVIEW|RESEARCH ADDITION)/i.test(html)) {
  throw new Error('Revised production HTML contains internal review comments.');
}
if (review.length < 1000) {
  throw new Error('Revised review document is unexpectedly short.');
}

const packageForStorage = {
  article_html: html,
  review_document_markdown: review,
  metadata: publicationPackage.metadata,
  openai_response_id: response.id,
  generated_at: new Date().toISOString(),
  revised_from_version: Number(context.current_version),
  revision_instruction: context.revision_instruction
};

return [{
  json: {
    article_id: context.article_id,
    interview_id: context.interview_id,
    campaign_id: context.campaign_id,
    doctor_id: context.doctor_id,
    practice_id: context.practice_id,
    approval_id: context.approval_id,
    current_version: Number(context.current_version),
    next_version: Number(context.next_version),
    doctor_review_days: Number(context.doctor_review_days || 5),
    revision_instruction: context.revision_instruction,
    package_json: JSON.stringify(packageForStorage),
    openai_response_id: response.id
  }
}];
